$('loanType').addEventListener('change',e=>{const installment=e.target.value==='installment';$('installmentMonthsLabel').hidden=!installment;$('loanForm').elements.months.required=installment;$('alreadyPaidLabel').hidden=installment;$('deadlineLabel').firstChild.textContent=installment?'First payment date':'Deadline';$('loanForm').elements.paid.required=false});
state.customCategories=Array.isArray(state.customCategories)?[...new Set(state.customCategories.filter(name=>typeof name==='string'&&name.trim()))]:[];state.customCategories=state.customCategories.filter(name=>![...categories.expense,...categories.income].includes(name));categories.expense.push(...state.customCategories);
