function setPasswordSetupFields(){const pin=$('passwordTypeSelector').value==='pin',label=pin?'PIN':'password',field=$('passwordSetupSecret'),confirmation=$('passwordSetupConfirmation');$('passwordSetupSecretLabel').firstChild.textContent=`New ${label}`;$('passwordSetupConfirmation').previousElementSibling.textContent=`Confirm ${label}`;field.inputMode=pin?'numeric':'text';field.maxLength=pin?12:64;field.minLength=pin?4:8;field.pattern=pin?'[0-9]{4,12}':'.{8,64}';confirmation.inputMode=field.inputMode;confirmation.maxLength=field.maxLength;confirmation.minLength=field.minLength;confirmation.pattern=field.pattern}
