function bytesToHex(bytes){return Array.from(bytes,value=>value.toString(16).padStart(2,'0')).join('')}
async function derivePasswordHash(secret,saltHex){const salt=saltHex?Uint8Array.from(saltHex.match(/.{2}/g),value=>parseInt(value,16)):window.crypto.getRandomValues(new Uint8Array(16));const key=await window.crypto.subtle.importKey('raw',new TextEncoder().encode(secret),'PBKDF2',false,['deriveBits']);const bits=await window.crypto.subtle.deriveBits({name:'PBKDF2',salt,iterations:PASSWORD_HASH_ITERATIONS,hash:'SHA-256'},key,256);return{salt:bytesToHex(salt),hash:bytesToHex(new Uint8Array(bits))}}
function sameHash(left,right){if(left.length!==right.length)return false;let difference=0;for(let index=0;index<left.length;index++)difference|=left.charCodeAt(index)^right.charCodeAt(index);return difference===0}
function renderAppLock(){const settings=state.securitySettings;const pin=settings.passwordType==='pin',canChooseMethod=settings.appPasswordEnabled&&settings.biometricsEnabled&&nativeAuthContainer&&Boolean(NativeBiometric),showChooser=canChooseMethod&&activeUnlockMethod==='choose';$('appUnlockLabel').firstChild.textContent=pin?'App PIN':'App password';$('passwordMethodLabel').textContent=pin?'MPIN Login':'Password Login';$('appUnlockInput').inputMode=pin?'numeric':'text';$('appUnlockInput').maxLength=pin?12:64;$('unlockMethodChooser').hidden=!showChooser;$('appLockForm').hidden=!settings.appPasswordEnabled||showChooser;$('unlockMethodBack').hidden=!canChooseMethod||showChooser;$('appLockDescription').textContent=showChooser?'Choose how you want to unlock.':`Enter your app ${pin?'PIN':'password'} to unlock.`}
