function unlockApp(){appLockActive=false;biometricAttemptActive=false;$('appLockDialog').close();$('appUnlockInput').value='';$('appLockFeedback').hidden=true;$('appUnlockError').hidden=true;document.body.classList.remove('app-locked')}
