function initializeProtectionLifecycle(){const protectedApp=state.securitySettings.appPasswordEnabled||state.securitySettings.biometricsEnabled;if(protectedApp)lockApp();const onResume=()=>{if(!appLockActive||$('appLockForm').hidden)return;setTimeout(()=>$('appUnlockInput').focus(),0)};if(nativeAuthContainer&&NativeApp){NativeApp.addListener('appStateChange',event=>{if(!event.isActive)lockApp();else onResume()}).catch(error=>{console.error('App lifecycle listener failed',error);notify('Automatic app locking could not start. Please restart the app.')})}else{document.addEventListener('visibilitychange',()=>{if(document.hidden)lockApp();else onResume()});window.addEventListener('pagehide',lockApp);window.addEventListener('pageshow',onResume)}if(protectedApp&&!$('appLockForm').hidden)setTimeout(()=>$('appUnlockInput').focus(),0)}
