$('categoryForm').addEventListener('submit',e=>{
  e.preventDefault();
  const form=e.currentTarget,name=form.elements.category.value.trim(),amount=Number(form.elements.amount.value),icon=form.elements.icon.value.trim();
  if(!name||['__proto__','constructor','prototype'].includes(name)){notify('Enter a valid category name.');return}
  if(!icon){notify('Choose an emoji icon for this category.');return}
  const existing=[...categories.expense,...categories.income].filter(item=>item!==editingCategory);
  if(existing.some(item=>item.toLocaleLowerCase()===name.toLocaleLowerCase())){notify('That category already exists. Choose a different name.');return}
  if(editingCategory){
    const previous=editingCategory,index=categories.expense.indexOf(previous);
    if(index<0){notify('This category could not be found.');resetCategoryForm();return}
    categories.expense[index]=name;
    if(previous!==name){
      state.transactions.forEach(transaction=>{if(transaction.category===previous)transaction.category=name});
      delete state.budgets[previous];
      state.customCategories=state.customCategories.map(category=>category===previous?name:category);
      delete state.categoryIcons[previous];
    }
    state.budgets[name]=amount;state.categoryIcons[name]=icon;resetCategoryForm();refresh();renderCategorySettings();notify('Budget category updated.');return;
  }
  state.customCategories.push(name);categories.expense.push(name);state.budgets[name]=amount;state.categoryIcons[name]=icon;resetCategoryForm();refresh();renderCategorySettings();notify('Budget category added.');
});
