$('loanDeleteForm').addEventListener('submit',e=>{
  const dialog=$('loanDeleteDialog'),type=dialog.dataset.deleteType;
  if(!type||type==='loan')return;
  e.preventDefault();e.stopImmediatePropagation();
  const id=dialog.dataset.deleteId;
  if(type==='transaction'){
    const exists=state.transactions.some(item=>item.id===id);
    if(!exists){notify('This transaction could not be found. It may already have been removed.');dialog.close();return}
    state.transactions=state.transactions.filter(item=>item.id!==id);dialog.close();refresh();notify('Transaction removed.');return;
  }
  if(type==='category'){
    if(!categories.expense.includes(id)||id==='Loan payments'){notify('This category could not be found. It may already have been removed.');dialog.close();return}
    state.customCategories=state.customCategories.filter(name=>name!==id);
    categories.expense=categories.expense.filter(name=>name!==id);
    delete state.budgets[id];delete state.categoryIcons[id];
    if(editingCategory===id)resetCategoryForm();
    dialog.close();refresh();renderCategorySettings();notify('Category removed. Existing transactions were kept.');
  }
},true);
